SELECT DISTINCT UPPER(e.emp_name) as employee_name, CAST(e.salary AS DECIMAL(10,2)) as employee_salary, UPPER(e.country) as employee_country, LOWER(d.dept_name) as department_name, s.sale_id, CAST(s.amount AS DECIMAL(10,2)) as sale_amount, s.region FROM workspace.sql_optimizer_tests.sales s INNER JOIN workspace.sql_optimizer_tests.employees e ON s.emp_id = e.emp_id INNER JOIN workspace.sql_optimizer_tests.departments d ON e.dept_id = d.dept_id WHERE s.sale_date >= '2024-01-01' AND s.sale_date < '2024-07-01' AND UPPER(e.country) = 'USA' AND LOWER(d.dept_name) LIKE '%engineering%' AND s.amount > 5000 ORDER BY sale_amount DESC;